"""JSON audio WebSocket channel."""

from __future__ import annotations

import base64
import json
import re
import uuid
from typing import Any, Dict, Optional

import structlog
from sanic import (  # type: ignore[attr-defined]
    Blueprint,
    HTTPResponse,
    Request,
    Websocket,
    response,
)

from rasa.core.channels.channel import RuntimeAgent
from rasa.core.channels.voice_ready.utils import CallParameters
from rasa.core.channels.voice_stream.audio_bytes import L16_16KHZ, RasaAudioBytes
from rasa.core.channels.voice_stream.tts.tts_engine import TTSEngine
from rasa.core.channels.voice_stream.util import repack_voice_credentials
from rasa.core.channels.voice_stream.voice_channel import (
    ContinueConversationAction,
    MarkerInput,
    MarkerMessageOutput,
    NewAudioAction,
    PlaybackMarkerAckAction,
    VoiceChannelAction,
    VoiceInputChannel,
    VoiceOutputChannel,
)

logger = structlog.get_logger()

JSON_AUDIO_AUDIO_MESSAGE_TYPE = "audio"
JSON_AUDIO_MARK_MESSAGE_TYPE = "mark"
JSON_AUDIO_CLEAR_MESSAGE_TYPE = "clear"
JSON_AUDIO_SENDER_ID_HEADER = "X-Rasa-Sender"
_SENDER_ID_PATTERN = re.compile(r"^[A-Za-z0-9._:-]{1,128}$")


class JsonAudioOutputChannel(VoiceOutputChannel):
    """Output channel for a JSON audio WebSocket protocol."""

    @classmethod
    def name(cls) -> str:
        return "json_audio"

    def rasa_audio_bytes_to_channel_bytes(
        self, rasa_audio_bytes: RasaAudioBytes
    ) -> bytes:
        return rasa_audio_bytes.data

    def channel_bytes_to_message(self, recipient_id: str, channel_bytes: bytes) -> str:
        return json.dumps(
            {
                "type": JSON_AUDIO_AUDIO_MESSAGE_TYPE,
                "audio": base64.b64encode(channel_bytes).decode("utf-8"),
            }
        )

    def create_marker_message(self, marker_input: MarkerInput) -> MarkerMessageOutput:
        marker_id = uuid.uuid4().hex
        return MarkerMessageOutput(
            message_id=marker_id,
            message=json.dumps(
                {
                    "type": JSON_AUDIO_MARK_MESSAGE_TYPE,
                    "mark": {"name": marker_id},
                }
            ),
        )


class JsonAudioInputChannel(VoiceInputChannel):
    """Input channel for a JSON audio WebSocket protocol."""

    requires_voice_license = False

    def __init__(
        self,
        server_url: str,
        asr_config: Dict[str, Any],
        tts_config: Dict[str, Any],
        interruptions: Optional[Dict[str, int]] = None,
        silence_timeout: Optional[float | int] = None,
        **voice_config: Any,
    ) -> None:
        super().__init__(
            server_url,
            asr_config,
            tts_config,
            interruptions,
            **voice_config,
        )
        self.audio_format = L16_16KHZ
        self.silence_timeout = silence_timeout

    @classmethod
    def name(cls) -> str:
        return "json_audio"

    @classmethod
    def from_credentials(
        cls, credentials: Optional[Dict[str, Any]]
    ) -> "JsonAudioInputChannel":
        cls.validate_basic_credentials(credentials)
        return cls(**repack_voice_credentials(credentials or {}))

    def channel_bytes_to_rasa_audio_bytes(self, input_bytes: bytes) -> RasaAudioBytes:
        return RasaAudioBytes(input_bytes, format=self.audio_format)

    async def collect_call_parameters(
        self,
        channel_websocket: Websocket,
        request: Optional[Request] = None,
    ) -> Optional[CallParameters]:
        sender_id = (
            request.headers.get(JSON_AUDIO_SENDER_ID_HEADER) if request else None
        )
        call_id = (
            sender_id
            if sender_id and _SENDER_ID_PATTERN.fullmatch(sender_id)
            else f"json-audio-{uuid.uuid4()}"
        )
        logger.info("json_audio.call_started", call_id=call_id)
        return CallParameters(
            call_id=call_id,
            user_phone="json_audio",
            bot_phone="json_audio",
            stream_id=call_id,
        )

    async def map_input_message(
        self,
        message: Any,
        ws: Websocket,
    ) -> VoiceChannelAction:
        data = json.loads(message)
        if data.get("type") == JSON_AUDIO_AUDIO_MESSAGE_TYPE:
            channel_bytes = base64.b64decode(data["audio"])
            return NewAudioAction(self.channel_bytes_to_rasa_audio_bytes(channel_bytes))

        if data.get("type") == JSON_AUDIO_MARK_MESSAGE_TYPE:
            marker = data.get("mark") or {}
            marker_id = marker.get("name")
            if isinstance(marker_id, str) and marker_id:
                return PlaybackMarkerAckAction(marker_id=marker_id)

        return ContinueConversationAction()

    async def interrupt_playback(
        self, ws: Websocket, call_parameters: CallParameters
    ) -> None:
        """Ask the transport to discard audio already buffered for playback."""
        await ws.send(json.dumps({"type": JSON_AUDIO_CLEAR_MESSAGE_TYPE}))

    def create_output_channel(
        self, voice_websocket: Websocket, tts_engine: TTSEngine
    ) -> VoiceOutputChannel:
        return JsonAudioOutputChannel(
            voice_websocket=voice_websocket,
            tts_engine=tts_engine,
            tts_cache=self.tts_cache,
            audio_format=self.audio_format,
        )

    def conversation_blueprint(self, agent: RuntimeAgent) -> Blueprint:
        """Register JSON audio health and WebSocket routes."""
        blueprint = Blueprint("json_audio", __name__)

        @blueprint.route("/", methods=["GET"])
        async def health(_: Request) -> HTTPResponse:
            return response.json({"status": "ok"})

        @blueprint.websocket("/websocket")  # type: ignore[misc]
        async def handle_message(request: Request, ws: Websocket) -> None:
            try:
                await self.run_audio_streaming(agent, ws, request=request)
            except Exception as error:
                logger.error("json_audio.websocket.error", error=str(error))
                await ws.close(code=1011, reason="Error during audio streaming")

        return blueprint
